import{_ as o,l as i,o as a,c as l,v as r,p as c,x as t,d as n,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"RISC-V 特权手册对照","description":"","frontmatter":{"title":"RISC-V 特权手册对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/riscv-priv-spec.md","filePath":"cs/riscv-priv-spec.md","lastUpdated":1789023840000}'),h={name:"cs/riscv-priv-spec.md"};function u(m,e,S,A,I,_){const s=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="risc-v-特权手册对照" tabindex="-1">RISC-V 特权手册对照 <a class="header-anchor" href="#risc-v-特权手册对照" aria-label="Permalink to &quot;RISC-V 特权手册对照&quot;">​</a></h1><div class="epigraph"><p>Volume II 把 M/S/U、CSR、陷入与虚存写成对 Volume I 用户 ISA 的补充契约；页表与中断入口是手册里的状态机，不是操作系统源码。</p><footer>—— The RISC-V Instruction Set Manual, Volume II: Privileged Architecture</footer></div><p><a href="/cs/tanenbaum-mos">上一课</a>附录对照了 MOS 教材地图。附录对照，不插入主干。主干已在<a href="/cs/riscv-int-isa">RISC-V 整数指令</a>、<a href="/cs/privilege-rings">特权级</a>、<a href="/cs/exception-interrupt-entry">异常与中断入口</a>、<a href="/cs/multi-level-page-table">多级页表</a>里按教学需要取用手册；这里对照 <strong>特权手册的问题</strong>：用户 ISA 不够运行内核时，硬件必须提供哪些额外状态与陷阱。不重画单周期数据通路，也不把本篇插回组成课中间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Volume I 给出 RV32I 对寄存器与内存的变换。特权手册的缺口是：模式、<code>mstatus</code>/<code>sstatus</code>、陷入向量、<code>satp</code> 与页表格式、内存保护。Tanenbaum 从 OS 讲资源；手册从硬件契约讲「内核凭什么比用户多几条指令」。主干组成课已经用这份契约接上中断与页表；附录对照原文结构，避免把 Linux 当 ISA。</p><p><span class="marginnote">手册有版本。主干取教学稳定的 M/S/U 与 Sv32/Sv39 直觉，不跟踪每年扩展字母汤。型号审计仍是附录级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照章节：特权级与 CSR 列表、陷阱处理、物理内存保护、虚存。主干<a href="/cs/kernel-user">内核与用户态</a> 把手册的模式收成 OS 边界；<a href="/cs/syscall-path">系统调用路径</a> 对应 <code>ecall</code>。附录不把全部 CSR 地址背进课序。</p>',8)),(a(),c(p,null,{default:t(()=>[d(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20V1%5B%22Volume%20I%3A%20%E7%94%A8%E6%88%B7%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20V2%5B%22Volume%20II%3A%20%E6%A8%A1%E5%BC%8F%E4%B8%8E%E9%99%B7%E5%85%A5%22%5D%0A%20%20V2%20--%3E%20VM%5B%22%E9%A1%B5%E8%A1%A8%E4%B8%8E%20satp%22%5D%0A%20%20V2%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E7%89%B9%E6%9D%83%E7%BA%A7%20%2F%20%E9%A1%B5%E8%A1%A8%E8%AF%BE%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>手册让「引用监视器」有硬件牙齿：用户写不了 <code>mtvec</code>。这与 Lampson 矩阵、THE 分层同方向、不同层。网络教材下一篇对照的是 Kurose/Ross，对象换成协议栈，不再加 CSR。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干必须在单周期与流水线课用一份具体 ISA 接线；把整本 Volume II 插在 MOS 之后当「下一课组成」，课序会倒流。本篇只对照手册作为组成/OS 边界的出处。文献序列在网络教材后再停。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 OpenSBI 或某块开发板设备树写进本附录当必读。也不要在此开虚拟化扩展的全部二阶段页表——主干 EPT 课已点到为止。下一篇对照 Kurose and Ross。</p><p>对照结束应回到主干<a href="/cs/privilege-rings">特权级</a>与<a href="/cs/demand-paging">按需调页</a>。手册不插入安全课之后当续篇组成。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 RISC-V Volume II：模式、CSR、陷入、虚存契约。</li><li>主干组成与 OS 课已取用；本篇不插入流水线课中间。</li><li>出处：RISC-V Privileged Architecture 手册。</li></ul>',9))])}const V=o(h,[["render",u]]);export{f as __pageData,V as default};
